//! ucrtbase.dll (all `api-ms-win-crt-*` API sets resolve here).
//!
//! The exe and its DLLs use the dynamic UCRT; vcruntime140/msvcp140 are the
//! real Microsoft DLLs from the game directory (loaded as PEs) and call into
//! this module. Export table generated by build.rs from all files here.

pub mod convert;
pub mod env;
pub mod errno;
pub mod heap;
pub mod locale;
pub mod math;
pub mod printf;
pub mod runtime;
pub mod scanf;
pub mod stdio;
pub mod string;
pub mod time;

pub static EXPORTS: &[crate::Export] = include!(concat!(env!("OUT_DIR"), "/ucrt_exports.rs"));
